"""Sum bank-export CSVs into per-account totals.

Usage: python3 ledger.py <exports-dir>

Every *.csv file in the directory is read in name order. Each line is
`date,account,amount`; there is no header. Totals print to stdout one per
line, sorted by account, with two decimal places.

Rows that cannot be parsed (the bank writes `N/A` in the amount column
sometimes) are left out of the totals and each one is reported on stderr
with its file and line number, followed by the accounts whose totals are
therefore incomplete.

Exit codes:
  0  every row parsed; totals are complete
  1  some rows were rejected; totals printed but incomplete (see stderr)
  2  usage error
"""
import sys
from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from pathlib import Path


@dataclass(frozen=True)
class Entry:
    date: str
    account: str
    amount: Decimal


@dataclass(frozen=True)
class Rejected:
    source: str  # "file:line", so the bad row can be found in the export
    line: str
    reason: str
    account: str | None  # known when the row split into fields, else None


@dataclass(frozen=True)
class Ledger:
    totals: dict[str, Decimal]
    rejected: list[Rejected]


def parse_row(source, line):
    # [LAW:parse-dont-validate] the one unit where a raw export line becomes an
    # Entry; failure is a typed Rejected the caller must handle, never a skip.
    fields = line.split(",")
    if len(fields) != 3:
        return Rejected(source, line, f"expected 3 fields, got {len(fields)}", None)
    date, account, raw_amount = fields
    try:
        amount = Decimal(raw_amount)
    except InvalidOperation:
        return Rejected(source, line, f"amount {raw_amount!r} is not a number", account)
    # Decimal accepts "NaN" and "Infinity", which would poison a total silently.
    if not amount.is_finite():
        return Rejected(source, line, f"amount {raw_amount!r} is not finite", account)
    return Entry(date, account, amount)


def read_rows(path):
    for number, line in enumerate(path.read_text().splitlines(), start=1):
        if line.strip():
            yield parse_row(f"{path}:{number}", line)


def build_ledger(exports_dir):
    totals, rejected = {}, []
    for path in sorted(Path(exports_dir).glob("*.csv")):
        for row in read_rows(path):
            match row:
                case Entry(account=account, amount=amount):
                    totals[account] = totals.get(account, Decimal("0")) + amount
                case Rejected():
                    rejected.append(row)
    return Ledger(totals, rejected)


def main(argv):
    if len(argv) != 2:
        print("usage: python3 ledger.py <exports-dir>", file=sys.stderr)
        return 2
    ledger = build_ledger(argv[1])
    for account, total in sorted(ledger.totals.items()):
        print(f"{account} {total:.2f}")
    # [LAW:no-silent-failure] rejected rows are excluded, never zero-filled:
    # each is named on stderr and the exit code says the totals are incomplete.
    for r in ledger.rejected:
        print(f"rejected {r.source}: {r.reason}: {r.line}", file=sys.stderr)
    affected = sorted({r.account or "<unknown account>" for r in ledger.rejected})
    if affected:
        print(f"incomplete totals: {', '.join(affected)}", file=sys.stderr)
    return 1 if ledger.rejected else 0


if __name__ == "__main__":
    sys.exit(main(sys.argv))
EOF
